<?php require dirname(__DIR__).'/inc/page_helpers.php';login_required();$q=$db->prepare('SELECT c.id,c.name,c.type FROM inventory i JOIN catalog_items c ON c.id=i.item_id WHERE i.user_id=?');$q->execute([$currentUser['id']]);$items=$q->fetchAll();page_start('My Character');?><section class="Panel"><h1>My Character</h1><?php foreach($items as $i):?><p><a href="/Item.php?id=<?=(int)$i['id']?>"><?=e($i['name'])?></a> (<?=e($i['type'])?>)</p><?php endforeach;?><?php if(!$items):?><p>Inventory empty. Visit the <a href="/Catalog.php">Catalog</a>.</p><?php endif;?></section><?php page_end();